WITH B AS (SELECT CODBAI,REGEXP_REPLACE(TRIM(TRANSLATE(UPPER(NOMEBAI),'ÁÂÍÓÒÔÚÇç','AAAAAEEEEIIIIOOOOOUUUUCAAAAAEEEEIIIIOOOOOUUUUCA')),' {2,}',' ') K FROM TSIBAI), E AS (SELECT CODEND,TIPO,REGEXP_REPLACE(TRIM(TRANSLATE(UPPER(NOMEEND),'ÁÂÍÓÒÔÚÇç','AAAAAEEEEIIIIOOOOOUUUUCAAAAAEEEEIIIIOOOOOUUUUCA')),' {2,}',' ') K FROM TSIEND) SELECT 'BAIRROS' TIPO,COUNT(*) GRUPOS,SUM(QTD-1) OBSOLETOS FROM (SELECT K,COUNT(*) QTD FROM.  B GROUP BY HAVING COUNT(*)>1) UNION ALL SELECT 'ENDERECOS',COUNT(*),SUM(QTD-1).  FR.  M (SELECT TIPO,K,COUNT(*) QTD FROM E GROUP BTIPO,HAVING COUNT(*)>1);
